window.BOOK={"key":"usulsunna","app":"mutoon","lsk":"mutoon_usulsunna_v1","title":"أصول السنة","unitWord":"فقرة","sub":"أصول السنة برواية عبدوس بن مالك العطار · العقيدة · الإمام أحمد بن حنبل (ت ٢٤١هـ) · ١٢ بابًا","source":"https://ketabonline.com/ar/books/64495 (المتن المرقم 1-50 في «شرح أصول السنة» لابن جبرين، تحقيق أبي أنس علي أبو لوز، على نشرة الوليد بن محمد نبيه سيف النصر) + https://ketabonline.com/ar/books/10040 (عمر الحربي) + https://ketabonline.com/ar/books/92461 (تمام المنة لناصر السيف) ; مقابَل بـ https://shamela.ws/book/6418 (دار المنار 1411، نسخة الألباني عن الظاهرية) ; فاتحة الإسناد المختصرة من https://ketabonline.com/ar/books/29565 (الجامع لعلوم الإمام أحمد) ; الشكل من ضبط المحقق ومن نصوص مشكولة منشورة (شرح الطحاوية لابن أبي العز ط الرسالة، نشرات الواسطية، كتاب التوحيد، شروح اللمعة) · قوبل بـ: word-by-word script collation of K (Abu Lawz), H (al-Harbi), N (Nasir al-Sayf) with S (Shamela/Albani copy) as tie-breaker; harakat only from the editor's own marks or where a 3-word run matches a vocalized published text; the rest is left bare - see usulsunna-sources.md","note":"اللفظ هو المتن المتداول المرقم ١–٥٠، مقابَلًا آليًّا كلمةً كلمةً بنشرتي عمر الحربي وناصر السيف وبنسخة الألباني عن الظاهرية (الشاملة). لا توجد نسخة رقمية مشكولة كاملة: الشكل من ضبط المحقق ومن نصوص مشكولة منشورة فقط، فنحو ثلث الكلمات مشكول والباقي بلا شكل. ما لم يكن مشكولًا في الطبعات أكمل شكله الذكاء الاصطناعي، ويحسن مراجعته على شيخ.","chapters":[{"id":"us1","title":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ","units":[{"id":"us1_1","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ١","segs":[["matn","قَالَ عَبْدُوسُ: سَمِعْتُ أَبَا عَبْدِ اللَّهِ أَحْمَدَ بْنَ حَنْبَلٍ يَقُولُ: أُصُولُ السُّنَّةِ عِنْدَنَا:"]]},{"id":"us1_2","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ٢","segs":[["matn","التَّمَسُّكُ بِمَا كَانَ عَلَيْهِ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالِاقْتِدَاءُ بِهِمْ"]]},{"id":"us1_3","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ٣","segs":[["matn","وَتَرْكُ الْبِدَعِ، وَكُلُّ بِدْعَةٍ فَهِيَ ضَلَالَةٌ. وَتَرْكُ الْخُصُومَاتِ وَالْجُلُوسِ مَعَ أَصْحَابِ الْأَهْوَاءِ."]]},{"id":"us1_4","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ٤","segs":[["matn","وَتَرْكُ الْمِرَاءِ وَالْجِدَالِ وَالْخُصُومَاتِ فِي الدِّينِ. وَالسُّنَّةُ عِنْدَنَا آثَارُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"]]},{"id":"us1_5","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ٥","segs":[["matn","وَالسُّنَّةُ تُفَسِّرُ الْقُرْآنَ وَهِيَ دَلَائِلُ الْقُرْآنِ. وَلَيْسَ فِي السُّنَّةِ قِيَاسٌ."]]},{"id":"us1_6","label":"مُقَدِّمَةٌ: لُزُومُ السُّنَّةِ وَتَرْكُ الْبِدَعِ · ٦","segs":[["matn","وَلَا تُضْرَبُ لَهَا الْأَمْثَالُ. وَلَا تُدْرَكُ بِالْعُقُولِ وَلَا الْأَهْوَاءِ، إِنَّمَا هُوَ الِاتِّبَاعُ وَتَرْكُ الْهَوَى."]]}]},{"id":"us2","title":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ","units":[{"id":"us2_1","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ١","segs":[["matn","وَمِنَ السُّنَّةِ اللَّازِمَةِ الَّتِي مَنْ تَرَكَ مِنْهَا خَصْلَةً، وَلَمْ يَقْبَلْهَا وَيُؤْمِنْ بِهَا لَمْ يَكُنْ مِنْ أَهْلِهَا: الْإِيمَانُ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ، وَالتَّصْدِيقُ بِالْأَحَادِيثِ فِيهِ، وَالْإِيمَانُ بِهَا لَا يُقَالُ: لِمَ؟ وَلَا كَيْفَ؟ إِنَّمَا هُوَ التَّصْدِيقُ وَالْإِيمَانُ بِهَا."]]},{"id":"us2_2","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ٢","segs":[["matn","وَمَنْ لَمْ يَعْرِفْ تَفْسِيرَ الْحَدِيثِ، وَيَبْلُغْهُ عَقْلُهُ، فَقَدْ كُفِيَ ذَلِكَ وَأُحْكِمَ لَهُ، فَعَلَيْهِ الْإِيمَانُ بِهِ وَالتَّسْلِيمُ لَهُ."]]},{"id":"us2_3","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ٣","segs":[["matn","مِثْلُ حَدِيثِ الصَّادِقِ الْمَصْدُوقِ وَمِثْلُ مَا كَانَ مِثْلَهُ فِي الْقَدَرِ"]]},{"id":"us2_4","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ٤","segs":[["matn","وَمِثْلُ أَحَادِيثِ الرُّؤْيَةِ كُلِّهَا، وَإِنْ نَبَتْ عَنِ الْأَسْمَاعِ وَاسْتَوْحَشَ مِنْهَا الْمُسْتَمِعُ."]]},{"id":"us2_5","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ٥","segs":[["matn","وَإِنَّمَا عَلَيْهِ الْإِيمَانُ بِهَا، وَأَنْ لَا يَرُدَّ مِنْهَا حَرْفًا وَاحِدًا. وَغَيْرِهَا مِنَ الْأَحَادِيثِ الْمَأْثُورَاتِ عَنِ الثِّقَاتِ."]]},{"id":"us2_6","label":"الْإِيمَانُ بِالْقَدَرِ وَالتَّسْلِيمُ لِلْأَحَادِيثِ · ٦","segs":[["matn","وَأَنْ لَا يُخَاصِمَ أَحَدًا، وَلَا يُنَاظِرَهُ، وَلَا يَتَعَلَّمَ الْجِدَالَ، فَإِنَّ الْكَلَامَ فِي الْقَدَرِ وَالرُّؤْيَةِ وَالْقُرْآنِ وَغَيْرِهَا مِنَ السُّنَنِ مَكْرُوهٌ، وَمَنْهِيٌّ عَنْهُ، لَا يَكُونُ صَاحِبُهُ وَإِنْ أَصَابَ بِكَلَامِهِ السُّنَّةَ مِنْ أَهْلِ السُّنَّةِ حَتَّى يَدَعَ الْجِدَالَ وَيُسَلِّمَ، وَيُؤْمِنَ بِالْآثَارِ."]]}]},{"id":"us3","title":"الْقُرْآنُ كَلَامُ اللَّهِ","units":[{"id":"us3_1","label":"الْقُرْآنُ كَلَامُ اللَّهِ · ١","segs":[["matn","وَالْقُرْآنُ كَلَامُ اللَّهِ وَلَيْسَ بِمَخْلُوقٍ وَلَا يَضْعُفُ أَنْ يَقُولَ: لَيْسَ بِمَخْلُوقٍ، قَالَ: فَإِنَّ كَلَامَ اللَّهِ لَيْسَ بِبَائِنٍ مِنْهُ، وَلَيْسَ مِنْهُ شَيْءٌ مَخْلُوقٌ، وَإِيَّاكَ وَمُنَاظَرَةَ مَنْ أَحْدَثَ فِيهِ وَمَنْ قَالَ بِاللَّفْظِ وَغَيْرِهِ،"]]},{"id":"us3_2","label":"الْقُرْآنُ كَلَامُ اللَّهِ · ٢","segs":[["matn","وَمَنْ وَقَفَ فِيهِ فَقَالَ: لَا أَدْرِي، مَخْلُوقٌ أَوْ لَيْسَ بِمَخْلُوقٍ، وَإِنَّمَا هُوَ كَلَامُ اللَّهِ، فَهَذَا صَاحِبُ بِدْعَةٍ مِثْلُ مَنْ قَالَ: هُوَ مَخْلُوقٌ. وَإِنَّمَا هُوَ كَلَامُ اللَّهِ لَيْسَ بِمَخْلُوقٍ"]]}]},{"id":"us4","title":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ","units":[{"id":"us4_1","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ١","segs":[["matn","وَالْإِيمَانُ بِالرُّؤْيَةِ يَوْمَ الْقِيَامَةِ كَمَا رُوِيَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَحَادِيثِ الصِّحَاحِ."]]},{"id":"us4_2","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٢","segs":[["matn","وَأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ رَأَى رَبَّهُ، فَإِنَّهُ مَأْثُورٌ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَحِيحٌ."]]},{"id":"us4_3","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٣","segs":[["matn","رَوَاهُ قَتَادَةُ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ وَرَوَاهُ الْحَكَمُ بْنُ أَبَانَ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ وَرَوَاهُ عَلِيُّ بْنُ زَيْدٍ عَنْ يُوسُفَ بْنِ مِهْرَانَ عَنِ ابْنِ عَبَّاسٍ وَالْحَدِيثُ عِنْدَنَا عَلَى ظَاهِرِهِ،"]]},{"id":"us4_4","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٤","segs":[["matn","كَمَا جَاءَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالْكَلَامُ فِيهِ بِدْعَةٌ،"]]},{"id":"us4_5","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٥","segs":[["matn","وَلَكِنْ نُؤْمِنُ بِهِ كَمَا جَاءَ عَلَى ظَاهِرِهِ، وَلَا نُنَاظِرُ فِيهِ أَحَدًا."]]},{"id":"us4_6","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٦","segs":[["matn","وَالْإِيمَانُ بِالْمِيزَانِ يَوْمَ الْقِيَامَةِ، كَمَا جَاءَ: يُوزَنُ الْعَبْدُ يَوْمَ الْقِيَامَةِ فَلَا يَزِنُ جَنَاحَ بَعُوضَةٍ وَتُوزَنُ أَعْمَالُ الْعِبَادِ كَمَا جَاءَ فِي الْأَثَرِ وَالْإِيمَانُ بِهِ وَالتَّصْدِيقُ بِهِ، وَالْإِعْرَاضُ عَنْ مَنْ رَدَّ ذَلِكَ وَتَرْكُ مُجَادَلَتِهِ."]]},{"id":"us4_7","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٧","segs":[["matn","وَأَنَّ اللَّهَ تَعَالَى يُكَلِّمُ الْعِبَادَ يَوْمَ الْقِيَامَةِ لَيْسَ بَيْنَهُمْ وَبَيْنَهُ تُرْجُمَانٌ وَالْإِيمَانُ بِهِ وَالتَّصْدِيقُ بِهِ"]]},{"id":"us4_8","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٨","segs":[["matn","وَالْإِيمَانُ بِالْحَوْضِ وَأَنَّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَوْضًا يَوْمَ الْقِيَامَةِ تَرِدُ عَلَيْهِ أُمَّتُهُ عَرْضُهُ مِثْلُ طُولِهِ مَسِيرَةُ شَهْرٍ، آنِيَتُهُ كَعَدَدِ نُجُومِ السَّمَاءِ، عَلَى مَا صَحَّتْ بِهِ الْأَخْبَارُ مِنْ غَيْرِ وَجْهٍ."]]},{"id":"us4_9","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ٩","segs":[["matn","وَالْإِيمَانُ بِعَذَابِ الْقَبْرِ. وَأَنَّ هَذِهِ الْأُمَّةَ تُفْتَنُ فِي قُبُورِهَا وَتُسْأَلُ عَنِ الْإِيمَانِ وَالْإِسْلَامِ، وَمَنْ رَبُّهُ؟ وَمَنْ نَبِيُّهُ؟ وَيَأْتِيهِ مُنْكَرٌ وَنَكِيرٌ كَيْفَ شَاءَ اللَّهُ عَزَّ وَجَلَّ وَكَيْفَ أَرَادَ، وَالْإِيمَانُ بِهِ وَالتَّصْدِيقُ بِهِ."]]},{"id":"us4_10","label":"الرُّؤْيَةُ وَالْمِيزَانُ وَالْحَوْضُ وَعَذَابُ الْقَبْرِ وَالشَّفَاعَةُ · ١٠","segs":[["matn","وَالْإِيمَانُ بِشَفَاعَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِقَوْمٍ يَخْرُجُونَ مِنَ النَّارِ بَعْدَمَا احْتَرَقُوا وَصَارُوا فَحْمًا، فَيُؤْمَرُ بِهِمْ إِلَى نَهَرٍ عَلَى بَابِ الْجَنَّةِ كَمَا جَاءَ فِي الْأَثَرِ كَيْفَ شَاءَ اللَّهُ وَكَمَا شَاءَ. إِنَّمَا هُوَ الْإِيمَانُ بِهِ وَالتَّصْدِيقُ بِهِ."]]}]},{"id":"us5","title":"الدَّجَّالُ وَنُزُولُ عِيسَى","units":[{"id":"us5_1","label":"الدَّجَّالُ وَنُزُولُ عِيسَى · ١","segs":[["matn","وَالْإِيمَانُ أَنَّ الْمَسِيحَ الدَّجَّالَ خَارِجٌ، مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ وَالْأَحَادِيثُ الَّتِي جَاءَتْ فِيهِ، وَالْإِيمَانُ بِأَنَّ ذَلِكَ كَائِنٌ."]]},{"id":"us5_2","label":"الدَّجَّالُ وَنُزُولُ عِيسَى · ٢","segs":[["matn","وَأَنَّ عِيسَى ابْنَ مَرْيَمَ عَلَيْهِ السَّلَامُ يَنْزِلُ فَيَقْتُلُهُ بِبَابِ لُدٍّ"]]}]},{"id":"us6","title":"الْإِيمَانُ وَتَرْكُ الصَّلَاةِ","units":[{"id":"us6_1","label":"الْإِيمَانُ وَتَرْكُ الصَّلَاةِ · ١","segs":[["matn","وَالْإِيمَانُ قَوْلٌ وَعَمَلٌ يَزِيدُ وَيَنْقُصُ؛ كَمَا جَاءَ فِي الْخَبَرِ: أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا"]]},{"id":"us6_2","label":"الْإِيمَانُ وَتَرْكُ الصَّلَاةِ · ٢","segs":[["matn","وَمَنْ تَرَكَ الصَّلَاةَ فَقَدْ كَفَرَ وَلَيْسَ مِنَ الْأَعْمَالِ شَيْءٌ تَرْكُهُ كُفْرٌ إِلَّا الصَّلَاةُ مَنْ تَرَكَهَا فَهُوَ كَافِرٌ، وَقَدْ أَحَلَّ اللَّهُ قَتْلَهُ."]]}]},{"id":"us7","title":"فَضْلُ الصَّحَابَةِ","units":[{"id":"us7_1","label":"فَضْلُ الصَّحَابَةِ · ١","segs":[["matn","وَخَيْرُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا؛ أَبُو بَكْرٍ الصِّدِّيقُ ثُمَّ عُمَرُ بْنُ الْخَطَّابِ ثُمَّ عُثْمَانُ بْنُ عَفَّانَ نُقَدِّمُ هَؤُلَاءِ الثَّلَاثَةَ كَمَا قَدَّمَهُمْ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَخْتَلِفُوا فِي ذَلِكَ."]]},{"id":"us7_2","label":"فَضْلُ الصَّحَابَةِ · ٢","segs":[["matn","ثُمَّ بَعْدَ هَؤُلَاءِ الثَّلَاثَةِ أَصْحَابُ الشُّورَى الْخَمْسَةُ: عَلِيُّ بْنُ أَبِي طَالِبٍ وَطَلْحَةُ وَالزُّبَيْرُ وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ وَسَعْدٌ كُلُّهُمْ يَصْلُحُ لِلْخِلَافَةِ، وَكُلُّهُمْ إِمَامٌ،"]]},{"id":"us7_3","label":"فَضْلُ الصَّحَابَةِ · ٣","segs":[["matn","وَنَذْهَبُ فِي ذَلِكَ إِلَى حَدِيثِ ابْنِ عُمَرَ: كُنَّا نَعُدُّ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيٌّ وَأَصْحَابُهُ مُتَوَافِرُونَ: أَبُو بَكْرٍ ثُمَّ عُمَرُ ثُمَّ عُثْمَانُ ثُمَّ نَسْكُتُ"]]},{"id":"us7_4","label":"فَضْلُ الصَّحَابَةِ · ٤","segs":[["matn","ثُمَّ مِنْ بَعْدِ أَصْحَابِ الشُّورَى أَهْلُ بَدْرٍ مِنَ الْمُهَاجِرِينَ، ثُمَّ أَهْلُ بَدْرٍ مِنَ الْأَنْصَارِ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَدْرِ الْهِجْرَةِ وَالسَّابِقَةِ أَوَّلًا فَأَوَّلًا."]]},{"id":"us7_5","label":"فَضْلُ الصَّحَابَةِ · ٥","segs":[["matn","ثُمَّ أَفْضَلُ النَّاسِ بَعْدَ هَؤُلَاءِ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقَرْنُ الَّذِي بُعِثَ فِيهِمْ كُلُّ مَنْ صَحِبَهُ سَنَةً أَوْ شَهْرًا أَوْ يَوْمًا أَوْ سَاعَةً أَوْ رَآهُ فَهُوَ مِنْ أَصْحَابِهِ،"]]},{"id":"us7_6","label":"فَضْلُ الصَّحَابَةِ · ٦","segs":[["matn","لَهُ مِنَ الصُّحْبَةِ عَلَى قَدْرِ مَا صَحِبَهُ، وَكَانَتْ سَابِقَتُهُ مَعَهُ وَسَمِعَ مِنْهُ وَنَظَرَ إِلَيْهِ نَظْرَةً، فَأَدْنَاهُمْ صُحْبَةً هُوَ أَفْضَلُ مِنَ الْقَرْنِ الَّذِينَ لَمْ يَرَوْهُ، وَلَوْ لَقُوا اللَّهَ بِجَمِيعِ الْأَعْمَالِ؛"]]},{"id":"us7_7","label":"فَضْلُ الصَّحَابَةِ · ٧","segs":[["matn","كَانَ هَؤُلَاءِ الَّذِينَ صَحِبُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَأَوْهُ وَسَمِعُوا مِنْهُ، وَمَنْ رَآهُ بِعَيْنِهِ وَآمَنَ بِهِ وَلَوْ سَاعَةً أَفْضَلَ لِصُحْبَتِهِ مِنَ التَّابِعِينَ وَلَوْ عَمِلُوا كُلَّ أَعْمَالِ الْخَيْرِ"]]}]},{"id":"us8","title":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ","units":[{"id":"us8_1","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ١","segs":[["matn","وَالسَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ وَأَمِيرِ الْمُؤْمِنِينَ الْبَرِّ وَالْفَاجِرِ وَمَنْ وَلِيَ الْخِلَافَةَ، وَاجْتَمَعَ النَّاسُ عَلَيْهِ وَرَضُوا بِهِ، وَمَنْ عَلِيَهُمْ بِالسَّيْفِ حَتَّى صَارَ خَلِيفَةً وَسُمِّيَ أَمِيرَ الْمُؤْمِنِينَ"]]},{"id":"us8_2","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٢","segs":[["matn","وَالْغَزْوُ مَاضٍ مَعَ الْأُمَرَاءِ إِلَى يَوْمِ الْقِيَامَةِ الْبَرِّ وَالْفَاجِرِ لَا يُتْرَكُ."]]},{"id":"us8_3","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٣","segs":[["matn","وَقِسْمَةُ الْفَيْءِ، وَإِقَامَةُ الْحُدُودِ إِلَى الْأَئِمَّةِ مَاضٍ، لَيْسَ لِأَحَدٍ أَنْ يَطْعَنَ عَلَيْهِمْ، وَلَا يُنَازِعَهُمْ."]]},{"id":"us8_4","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٤","segs":[["matn","وَدَفْعُ الصَّدَقَاتِ إِلَيْهِمْ جَائِزَةٌ نَافِذَةٌ، مَنْ دَفَعَهَا إِلَيْهِمْ أَجْزَأَتْ عَنْهُ بَرًّا كَانَ أَوْ فَاجِرًا"]]},{"id":"us8_5","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٥","segs":[["matn","وَصَلَاةُ الْجُمُعَةِ خَلْفَهُ، وَخَلْفَ مَنْ وَلَّاهُ؛ جَائِزَةٌ بَاقِيَةٌ تَامَّةٌ رَكْعَتَيْنِ، مَنْ أَعَادَهُمَا فَهُوَ مُبْتَدِعٌ، تَارِكٌ لِلْآثَارِ، مُخَالِفٌ لِلسُّنَّةِ، لَيْسَ لَهُ مِنْ فَضْلِ الْجُمُعَةِ شَيْءٌ؛"]]},{"id":"us8_6","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٦","segs":[["matn","إِذَا لَمْ يَرَ الصَّلَاةَ خَلْفَ الْأَئِمَّةِ مَنْ كَانُوا بَرِّهِمْ وَفَاجِرِهِمْ، فَالسُّنَّةُ بِأَنْ يُصَلِّيَ مَعَهُمْ رَكْعَتَيْنِ وَيَدِينَ بِأَنَّهَا تَامَّةٌ، لَا يَكُنْ فِي صَدْرِكَ مِنْ ذَلِكَ شَكٌّ"]]},{"id":"us8_7","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٧","segs":[["matn","وَمَنْ خَرَجَ عَلَى إِمَامٍ مِنْ أَئِمَّةِ الْمُسْلِمِينَ وَقَدْ كَانَ النَّاسُ اجْتَمَعُوا عَلَيْهِ وَأَقَرُّوا لَهُ بِالْخِلَافَةِ بِأَيِّ وَجْهٍ كَانَ بِالرِّضَا أَوْ بِالْغَلَبَةِ فَقَدْ شَقَّ هَذَا الْخَارِجُ عَصَا الْمُسْلِمِينَ،"]]},{"id":"us8_8","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٨","segs":[["matn","وَخَالَفَ الْآثَارَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ مَاتَ الْخَارِجُ عَلَيْهِ مَاتَ مِيتَةً جَاهِلِيَّةً"]]},{"id":"us8_9","label":"السَّمْعُ وَالطَّاعَةُ لِلْأَئِمَّةِ · ٩","segs":[["matn","وَلَا يَحِلُّ قِتَالُ السُّلْطَانِ وَلَا الْخُرُوجُ عَلَيْهِ لِأَحَدٍ مِنَ النَّاسِ، فَمَنْ فَعَلَ ذَلِكَ فَهُوَ مُبْتَدِعٌ عَلَى غَيْرِ السُّنَّةِ وَالطَّرِيقِ"]]}]},{"id":"us9","title":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ","units":[{"id":"us9_1","label":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ · ١","segs":[["matn","وَقِتَالُ اللُّصُوصِ وَالْخَوَارِجِ جَائِزٌ إِذَا عَرَضُوا لِلرَّجُلِ فِي نَفْسِهِ وَمَالِهِ، فَلَهُ أَنْ يُقَاتِلَ عَنْ نَفْسِهِ وَمَالِهِ، وَيَدْفَعَ عَنْهَا بِكُلِّ مَا يَقْدِرُ، وَلَيْسَ لَهُ إِذَا فَارَقُوهُ أَوْ تَرَكُوهُ أَنْ يَطْلُبَهُمْ، وَلَا يَتَّبِعَ آثَارَهُمْ،"]]},{"id":"us9_2","label":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ · ٢","segs":[["matn","لَيْسَ لِأَحَدٍ إِلَّا الْإِمَامِ أَوْ وُلَاةِ الْمُسْلِمِينَ، إِنَّمَا لَهُ أَنْ يَدْفَعَ عَنْ نَفْسِهِ فِي مَقَامِهِ ذَلِكَ، وَيَنْوِيَ بِجُهْدِهِ أَنْ لَا يَقْتُلَ أَحَدًا، فَإِنْ مَاتَ عَلَى يَدَيْهِ فِي دَفْعِهِ عَنْ نَفْسِهِ فِي الْمَعْرَكَةِ فَأَبْعَدَ اللَّهُ الْمَقْتُولَ،"]]},{"id":"us9_3","label":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ · ٣","segs":[["matn","وَإِنْ قُتِلَ هَذَا فِي تِلْكَ الْحَالِ وَهُوَ يَدْفَعُ عَنْ نَفْسِهِ وَمَالِهِ رَجَوْتُ لَهُ الشَّهَادَةَ، كَمَا جَاءَ فِي الْأَحَادِيثِ."]]},{"id":"us9_4","label":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ · ٤","segs":[["matn","وَجَمِيعُ الْآثَارِ فِي هَذَا إِنَّمَا أُمِرَ بِقِتَالِهِ وَلَمْ يُؤْمَرْ بِقَتْلِهِ وَلَا اتِّبَاعِهِ، وَلَا يُجِيزُ عَلَيْهِ إِنْ صُرِعَ أَوْ كَانَ جَرِيحًا."]]},{"id":"us9_5","label":"قِتَالُ اللُّصُوصِ وَالْخَوَارِجِ · ٥","segs":[["matn","وَإِنْ أَخَذَهُ أَسِيرًا فَلَيْسَ لَهُ أَنْ يَقْتُلَهُ، وَلَا يُقِيمَ عَلَيْهِ الْحَدَّ، وَلَكِنْ يَرْفَعُ أَمْرَهُ إِلَى مَنْ وَلَّاهُ اللَّهُ فَيَحْكُمُ فِيهِ."]]}]},{"id":"us10","title":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ","units":[{"id":"us10_1","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ١","segs":[["matn","وَلَا نَشْهَدُ عَلَى أَحَدٍ مِنْ أَهْلِ الْقِبْلَةِ بِعَمَلٍ يَعْمَلُهُ بِجَنَّةٍ وَلَا نَارٍ، نَرْجُو لِلصَّالِحِ، وَنَخَافُ عَلَيْهِ، وَنَخَافُ عَلَى الْمُسِيءِ الْمُذْنِبِ، وَنَرْجُو لَهُ رَحْمَةَ اللَّهِ."]]},{"id":"us10_2","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٢","segs":[["matn","وَمَنْ لَقِيَ اللَّهَ بِذَنْبٍ يَجِبُ لَهُ بِهِ النَّارُ تَائِبًا غَيْرَ مُصِرٍّ عَلَيْهِ فَإِنَّ اللَّهَ يَتُوبُ عَلَيْهِ، وَيَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَعْفُو عَنِ السَّيِّئَاتِ"]]},{"id":"us10_3","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٣","segs":[["matn","وَمَنْ لَقِيَهُ وَقَدْ أُقِيمَ عَلَيْهِ حَدُّ ذَلِكَ الذَّنْبِ فِي الدُّنْيَا فَهُوَ كَفَّارَتُهُ، كَمَا جَاءَ فِي الْخَبَرِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"]]},{"id":"us10_4","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٤","segs":[["matn","وَمَنْ لَقِيَهُ مُصِرًّا غَيْرَ تَائِبٍ مِنَ الذُّنُوبِ الَّتِي قَدِ اسْتَوْجَبَ بِهَا الْعُقُوبَةَ؛ فَأَمْرُهُ إِلَى اللَّهِ إِنْ شَاءَ عَذَّبَهُ وَإِنْ شَاءَ غَفَرَ لَهُ"]]},{"id":"us10_5","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٥","segs":[["matn","وَمَنْ لَقِيَهُ مِنْ كَافِرٍ عَذَّبَهُ وَلَمْ يَغْفِرْ لَهُ."]]},{"id":"us10_6","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٦","segs":[["matn","وَالرَّجْمُ حَقٌّ عَلَى مَنْ زَنَا وَقَدْ أُحْصِنَ إِذَا اعْتَرَفَ أَوْ قَامَتْ عَلَيْهِ بَيِّنَةٌ"]]},{"id":"us10_7","label":"أَهْلُ الْقِبْلَةِ وَالذُّنُوبُ وَالْحُدُودُ · ٧","segs":[["matn","وَقَدْ رَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ رَجَمَتِ الْأَئِمَّةُ الرَّاشِدُونَ"]]}]},{"id":"us11","title":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ","units":[{"id":"us11_1","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ١","segs":[["matn","وَمَنِ انْتَقَصَ أَحَدًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ أَبْغَضَهُ بِحَدَثٍ كَانَ مِنْهُ أَوْ ذَكَرَ مَسَاوِئَهُ كَانَ مُبْتَدِعًا حَتَّى يَتَرَحَّمَ عَلَيْهِمْ جَمِيعًا، وَيَكُونَ قَلْبُهُ لَهُمْ سَلِيمًا"]]},{"id":"us11_2","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ٢","segs":[["matn","وَالنِّفَاقُ هُوَ الْكُفْرُ: أَنْ يَكْفُرَ بِاللَّهِ وَيَعْبُدَ غَيْرَهُ،"]]},{"id":"us11_3","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ٣","segs":[["matn","وَيُظْهِرَ الْإِسْلَامَ فِي الْعَلَانِيَةِ مِثْلَ الْمُنَافِقِينَ الَّذِينَ كَانُوا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَوْلُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ هَذَا عَلَى التَّغْلِيظِ نَرْوِيهَا كَمَا جَاءَتْ، وَلَا نُفَسِّرُهَا."]]},{"id":"us11_4","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ٤","segs":[["matn","وَقَوْلُهُ: لَا تَرْجِعُوا بَعْدِي كُفَّارًا ضُلَّالًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ وَمِثْلُ: إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ وَمِثْلُ: سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ وَمِثْلُ:"]]},{"id":"us11_5","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ٥","segs":[["matn","مَنْ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ بَاءَ بِهَا أَحَدُهُمَا وَمِثْلُ: كُفْرٌ بِاللَّهِ تَبَرُّؤٌ مِنْ نَسَبٍ وَإِنْ دَقَّ وَنَحْوُ هَذِهِ الْأَحَادِيثِ مِمَّا قَدْ صَحَّ وَحُفِظَ، فَإِنَّا نُسَلِّمُ لَهُ، وَإِنْ لَمْ نَعْلَمْ تَفْسِيرَهَا وَلَا نَتَكَلَّمُ فِيهَا،"]]},{"id":"us11_6","label":"الصَّحَابَةُ وَالنِّفَاقُ وَأَحَادِيثُ الْوَعِيدِ · ٦","segs":[["matn","وَلَا نُجَادِلُ فِيهَا، وَلَا نُفَسِّرُ هَذِهِ الْأَحَادِيثَ إِلَّا مِثْلَ مَا جَاءَتْ لَا نَرُدُّهَا إِلَّا بِأَحَقَّ مِنْهَا."]]}]},{"id":"us12","title":"الْجَنَّةُ وَالنَّارُ وَالصَّلَاةُ عَلَى أَهْلِ الْقِبْلَةِ","units":[{"id":"us12_1","label":"الْجَنَّةُ وَالنَّارُ وَالصَّلَاةُ عَلَى أَهْلِ الْقِبْلَةِ · ١","segs":[["matn","وَالْجَنَّةُ وَالنَّارُ مَخْلُوقَتَانِ قَدْ خُلِقَتَا كَمَا جَاءَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلْتُ الْجَنَّةَ فَرَأَيْتُ قَصْرًا وَرَأَيْتُ الْكَوْثَرَ وَاطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا كَذَا وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ كَذَا وَكَذَا"]]},{"id":"us12_2","label":"الْجَنَّةُ وَالنَّارُ وَالصَّلَاةُ عَلَى أَهْلِ الْقِبْلَةِ · ٢","segs":[["matn","فَمَنْ زَعَمَ أَنَّهُمَا لَمْ تُخْلَقَا فَهُوَ مُكَذِّبٌ بِالْقُرْآنِ وَأَحَادِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا أَحْسِبُهُ يُؤْمِنُ بِالْجَنَّةِ وَالنَّارِ"]]},{"id":"us12_3","label":"الْجَنَّةُ وَالنَّارُ وَالصَّلَاةُ عَلَى أَهْلِ الْقِبْلَةِ · ٣","segs":[["matn","وَمَنْ مَاتَ مِنْ أَهْلِ الْقِبْلَةِ مُوَحِّدًا يُصَلَّى عَلَيْهِ، وَيُسْتَغْفَرُ لَهُ، وَلَا يُحْجَبُ عَنْهُ الِاسْتِغْفَارُ، وَلَا تُتْرَكُ الصَّلَاةُ عَلَيْهِ لِذَنْبٍ أَذْنَبَهُ صَغِيرًا كَانَ أَوْ كَبِيرًا أَمْرُهُ إِلَى اللَّهِ تَعَالَى وَالْحَمْدُ لِلَّهِ وَحْدَهُ وَصَلَوَاتُهُ عَلَى مُحَمَّدٍ وَآلِهِ وَسَلَّمَ تَسْلِيمًا."]]}]}],"sharh":false};
